$.get(url, params).done(function(data){
        for (var i = 0; i < data.length; i++) {
          var ev = data[i];
          ev.start = ev.start * 1000;
          ev.end = ev.end * 1000;
        }
        self.options.events = data;
        self.addCalendarEvents();
        self.options.onEventGet(data, self.$calendar);
      }).fail(function(data){
        self.options.onFetchFail(data);
      })

